1	// Package chainledger implements the on-chain data governance core.
2	//
3	// This file guards the plan reader against a silent name substitution.
4	// encoding/json decodes every JSON string by replacing each invalid UTF-8
5	// byte — and each \u escape that is an unpaired surrogate — with U+FFFD, so
6	// the decoded plan no longer contains the names the user actually wrote. A
7	// corrupted name can then collide with a real dataset: a removals entry
8	// written as "源" plus one broken byte decodes to "源�" and would delete the
9	// dataset genuinely named "源�". The reader must not guess which dataset the
10	// user meant, so any name that takes part in the lineage adjustment — the
11	// name of each change record, every upstreams entry, and every removals
12	// entry — is checked against its RAW string literal before the plan is
13	// accepted: a literal carrying bytes that are not valid UTF-8, or a \u
14	// escape forming an unpaired surrogate (a lone high or low surrogate, or a
15	// low surrogate written before its high surrogate), rejects the whole plan,
16	// even when the name would only have matched a dataset that does not exist.
17	//
18	// Only the raw literal can tell corruption apart from a genuine name: the
19	// replacement character itself ("�", or the equivalent JSON escape) is legal and
20	// stays accepted, as is every correctly paired surrogate escape. Names that
21	// merely LOOK like escapes (a backslash followed by an ordinary letter) are
22	// plain text to JSON and are never rejected for that reason.
23	//
24	// The scan walks the document with the same field recognition the plan
25	// reader and the duplicate-field scan use — known fields matched after JSON
26	// unescaping with Unicode case folding — so a name spelled "Name" or
27	// "name" is checked exactly like "name". Unknown fields and everything
28	// nested inside them are skipped; their strings never took part in the
29	// adjustment and are not checked. A document too malformed to walk is left
30	// to the regular parse, exactly as in duplicate_fields.go.
31	package chainledger
32	
33	import (
34		"encoding/json"
35		"fmt"
36		"strings"
37		"unicode/utf8"
38	)
39	
40	// checkPlanNameEncoding scans the raw plan JSON and rejects the whole plan
41	// when any name that participates in the adjustment — changes[i].name, any
42	// changes[i].upstreams[j], or any removals[i] — is written with a string
43	// literal the decoder cannot read faithfully (invalid UTF-8 bytes or an
44	// unpaired surrogate escape). The error names the field and the zero-based
45	// record or array position, and says which of the two corruptions occurred.
46	func checkPlanNameEncoding(data []byte) error {
47		return runFieldScan(data, func(dec *json.Decoder) error {
48			tok, err := scanToken(dec)
49			if err != nil {
50				return err
51			}
52			if delim, ok := tok.(json.Delim); !ok || delim != '{' {
53				return skipRest(dec, tok) // not an object: the regular parse reports it
54			}
55			for dec.More() {
56				key, err := scanKey(dec)
57				if err != nil {
58					return err
59				}
60				switch {
61				case strings.EqualFold(key, "changes"):
62					err := checkArrayElements(dec, func(dec *json.Decoder, index int) error {
63						return checkChangeRecordNameEncoding(dec, index)
64					})
65					if err != nil {
66						return err
67					}
68				case strings.EqualFold(key, "removals"):
69					err := checkArrayElements(dec, func(dec *json.Decoder, index int) error {
70						location := fmt.Sprintf("field %q at index %d", "removals", index)
71						return checkNameStringEncoding(dec, location)
72					})
73					if err != nil {
74						return err
75					}
76				default:
77					// Unknown field: ignored with everything nested inside it.
78					if err := skipValue(dec); err != nil {
79						return err
80					}
81				}
82			}
83			_, err = scanToken(dec) // closing '}'
84			return err
85		})
86	}
87	
88	// checkChangeRecordNameEncoding scans one change record of the "changes"
89	// array: the raw literals of its "name" value and of every element of its
90	// "upstreams" array are checked; every other field is skipped. index is the
91	// record's zero-based position, used in error locations.
92	func checkChangeRecordNameEncoding(dec *json.Decoder, index int) error {
93		tok, err := scanToken(dec)
94		if err != nil {
95			return err
96		}
97		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
98			return skipRest(dec, tok) // not an object: the regular parse reports it
99		}
100		for dec.More() {
101			key, err := scanKey(dec)
102			if err != nil {
103				return err
104			}
105			switch {
106			case strings.EqualFold(key, "name"):
107				location := fmt.Sprintf("field %q in the change record at index %d of %q", "name", index, "changes")
108				if err := checkNameStringEncoding(dec, location); err != nil {
109					return err
110				}
111			case strings.EqualFold(key, "upstreams"):
112				err := checkArrayElements(dec, func(dec *json.Decoder, item int) error {
113					location := fmt.Sprintf("field %q at index %d in the change record at index %d of %q", "upstreams", item, index, "changes")
114					return checkNameStringEncoding(dec, location)
115				})
116				if err != nil {
117					return err
118				}
119			default:
120				if err := skipValue(dec); err != nil {
121					return err
122				}
123			}
124		}
125		_, err = scanToken(dec) // closing '}'
126		return err
127	}
128	
129	// checkNameStringEncoding consumes one value and, when it is a string
130	// literal, validates its raw bytes with validateNameStringLiteral. A
131	// non-string value is skipped: the regular parse reports the type error.
132	func checkNameStringEncoding(dec *json.Decoder, location string) error {
133		var raw json.RawMessage
134		if err := dec.Decode(&raw); err != nil {
135			return errAbortScan
136		}
137		if len(raw) < 2 || raw[0] != '"' {
138			return nil
139		}
140		return validateNameStringLiteral(raw, location)
141	}
142	
143	// validateNameStringLiteral checks one raw JSON string literal (surrounding
144	// quotes included) for the two corruptions the decoder would silently
145	// rewrite to U+FFFD: bytes that are not valid UTF-8, and \u escapes forming
146	// an unpaired surrogate. The literal is known to be syntactically valid
147	// JSON (the regular parse already accepted the document), so escapes are
148	// well-formed; anything else unexpected aborts the scan and is left to that
149	// parse. location identifies the field and position in the error.
150	func validateNameStringLiteral(raw []byte, location string) error {
151		end := len(raw) - 1 // index of the closing quote
152		for i := 1; i < end; {
153			c := raw[i]
154			switch {
155			case c == '\\':
156				if i+1 >= end {
157					return errAbortScan
158				}
159				if raw[i+1] != 'u' {
160					i += 2 // \", \\, \/, \b, \f, \n, \r, \t
161					continue
162				}
163				if i+6 > end {
164					return errAbortScan
165				}
166				cp, ok := hex4(raw[i+2 : i+6])
167				if !ok {
168					return errAbortScan
169				}
170				i += 6
171				switch {
172				case isHighSurrogate(cp):
173					// A high surrogate is legal only as the first half of a
174					// pair: the very next escape must be its low surrogate.
175					if i+6 <= end && raw[i] == '\\' && raw[i+1] == 'u' {
176						if low, ok := hex4(raw[i+2 : i+6]); ok && isLowSurrogate(low) {
177							i += 6
178							continue
179						}
180					}
181					return unpairedSurrogateError(location)
182				case isLowSurrogate(cp):
183					// A lone low surrogate — including one written before its
184					// high surrogate — never forms a pair.
185					return unpairedSurrogateError(location)
186				}
187			case c < utf8.RuneSelf:
188				i++
189			default:
190				// A genuine U+FFFD decodes with size 3 and is accepted; only a
191				// byte the decoder cannot map (size 1) is corruption.
192				r, size := utf8.DecodeRune(raw[i:end])
193				if r == utf8.RuneError && size == 1 {
194					return invalidUTF8BytesError(location)
195				}
196				i += size
197			}
198		}
199		return nil
200	}
201	
202	// hex4 parses exactly four hexadecimal digits (one \u escape unit).
203	func hex4(b []byte) (rune, bool) {
204		var v rune
205		for _, c := range b {
206			v <<= 4
207			switch {
208			case c >= '0' && c <= '9':
209				v |= rune(c - '0')
210			case c >= 'a' && c <= 'f':
211				v |= rune(c-'a') + 10
212			case c >= 'A' && c <= 'F':
213				v |= rune(c-'A') + 10
214			default:
215				return 0, false
216			}
217		}
218		return v, true
219	}
220	
221	func isHighSurrogate(cp rune) bool { return cp >= 0xD800 && cp <= 0xDBFF }
222	func isLowSurrogate(cp rune) bool  { return cp >= 0xDC00 && cp <= 0xDFFF }
223	
224	// invalidUTF8BytesError reports a name whose raw string literal carries
225	// bytes that are not valid UTF-8.
226	func invalidUTF8BytesError(location string) error {
227		return fmt.Errorf("%w: %s contains invalid UTF-8 bytes", ErrInvalidArgument, location)
228	}
229	
230	// unpairedSurrogateError reports a name whose \u escapes form an unpaired
231	// surrogate (a lone high or low surrogate, or a low surrogate before its
232	// high surrogate).
233	func unpairedSurrogateError(location string) error {
234		return fmt.Errorf("%w: %s contains an unpaired surrogate escape", ErrInvalidArgument, location)
235	}
