package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"

	"github.com/asdhoaiqqq/chainledger-governance/chainledger"
)

func digest(gjson string) string {
	var gf struct {
		Datasets []chainledger.GraphDataset `json:"datasets"`
	}
	if err := json.Unmarshal([]byte(gjson), &gf); err != nil {
		panic(err)
	}
	adj := map[string][]string{}
	for _, ds := range gf.Datasets {
		names := append([]string{}, ds.Upstreams...)
		// dedupe+sort
		seen := map[string]bool{}
		var out []string
		for _, n := range names {
			if !seen[n] {
				seen[n] = true
				out = append(out, n)
			}
		}
		// simple insertion sort
		for i := 1; i < len(out); i++ {
			for j := i; j > 0 && out[j-1] > out[j]; j-- {
				out[j-1], out[j] = out[j], out[j-1]
			}
		}
		adj[ds.Name] = out
	}
	canon := struct {
		Datasets []chainledger.GraphDataset `json:"datasets"`
	}{}
	names := make([]string, 0, len(adj))
	for n := range adj {
		names = append(names, n)
	}
	for i := 1; i < len(names); i++ {
		for j := i; j > 0 && names[j-1] > names[j]; j-- {
			names[j-1], names[j] = names[j], names[j-1]
		}
	}
	for _, n := range names {
		ps := adj[n]
		if ps == nil {
			ps = []string{}
		}
		canon.Datasets = append(canon.Datasets, chainledger.GraphDataset{Name: n, Upstreams: ps})
	}
	b, _ := json.Marshal(canon)
	sum := sha256.Sum256(b)
	return "sha256:" + hex.EncodeToString(sum[:])
}

func main() {
	// 1. Collision scenario: root genuinely named "源�", another dataset's
	// upstream written as "源" + lone surrogate.
	collide := `{"datasets":[{"name":"源�","upstreams":[]},{"name":"d","upstreams":["源\uD800"]}]}`
	if _, err := chainledger.UnmarshalGraphFile([]byte(collide)); err == nil {
		fmt.Println("FAIL: colliding graph accepted")
	} else {
		fmt.Println("OK graph collision rejected:", err)
	}

	// 2. No collision: lone surrogate upstream with no matching dataset.
	noCollide := `{"datasets":[{"name":"源","upstreams":[]},{"name":"d","upstreams":["源\uD800"]}]}`
	if _, err := chainledger.UnmarshalGraphFile([]byte(noCollide)); err == nil {
		fmt.Println("FAIL: non-colliding corrupt graph accepted")
	} else {
		fmt.Println("OK graph no-collision rejected:", err)
	}

	// 3. Invalid bytes in name and in upstream.
	badName := `{"datasets":[{"name":"源` + "\xff" + `","upstreams":[]}]}`
	if _, err := chainledger.UnmarshalGraphFile([]byte(badName)); err == nil {
		fmt.Println("FAIL: invalid-byte name accepted")
	} else {
		fmt.Println("OK bytes in name rejected:", err)
	}
	badUp := `{"datasets":[{"name":"源","upstreams":[]},{"name":"d","upstreams":["源` + "\xfe" + `"]}]}`
	if _, err := chainledger.UnmarshalGraphFile([]byte(badUp)); err == nil {
		fmt.Println("FAIL: invalid-byte upstream accepted")
	} else {
		fmt.Println("OK bytes in upstream rejected:", err)
	}

	// 4. Surrogate variants: lone low, low-before-high, high then non-low.
	for _, g := range []string{
		`{"datasets":[{"name":"a\uDC00","upstreams":[]}]}`,
		`{"datasets":[{"name":"a\uDC00\uD800","upstreams":[]}]}`,
		`{"datasets":[{"name":"a","upstreams":["a\uD800A"]}]}`,
	} {
		if _, err := chainledger.UnmarshalGraphFile([]byte(g)); err == nil {
			fmt.Println("FAIL: surrogate variant accepted:", g)
		} else {
			fmt.Println("OK surrogate rejected:", err)
		}
	}

	// 5. Legal names: real U+FFFD, escape U+FFFD, paired surrogate, CJK, emoji,
	// literal backslash + letters, spaces/case/combining.
	for _, g := range []string{
		`{"datasets":[{"name":"源�","upstreams":[]}]}`,
		`{"datasets":[{"name":"源�","upstreams":[]}]}`,
		`{"datasets":[{"name":"ledger😀","upstreams":[]},{"name":" 数据 Éé ","upstreams":["ledger😀"]}]}`,
		`{"datasets":[{"name":"x\\ud800","upstreams":[]}]}`,
	} {
		gr, err := chainledger.UnmarshalGraphFile([]byte(g))
		if err != nil {
			fmt.Println("FAIL legal graph rejected:", err, g)
			continue
		}
		fmt.Println("OK legal graph accepted, nodes:", len(gr))
	}

	// 6. Unknown fields carry corrupt strings without error.
	unk := `{"meta":"a\uD800","datasets":[{"name":"A","note":"x` + "\xff" + `","upstreams":[]}]}`
	if _, err := chainledger.UnmarshalGraphFile([]byte(unk)); err != nil {
		fmt.Println("FAIL unknown-field strings triggered error:", err)
	} else {
		fmt.Println("OK unknown-field strings ignored")
	}

	// 7. Snapshot: declared contentId equals the post-replacement graph's
	// digest, yet it must be rejected for corrupt names.
	rewritten := `{"datasets":[{"name":"源�","upstreams":[]},{"name":"d","upstreams":["源�"]}]}`
	id := digest(rewritten)
	snap := `{"formatVersion":1,"contentId":"` + id + `","graph":` + collide + `}`
	if _, err := chainledger.ParseSnapshot([]byte(snap)); err == nil {
		fmt.Println("FAIL: corrupt-name snapshot accepted with matching contentId")
	} else {
		fmt.Println("OK snapshot with matching rewritten digest rejected:", err)
	}

	// 8. Snapshot corrupt bytes in embedded graph name rejected.
	snapBad := `{"formatVersion":1,"contentId":"x","graph":{"datasets":[{"name":"a` + "\xff" + `","upstreams":[]}]}}`
	if _, err := chainledger.ParseSnapshot([]byte(snapBad)); err == nil {
		fmt.Println("FAIL: corrupt bytes in snapshot graph accepted")
	} else {
		fmt.Println("OK snapshot bytes rejected:", err)
	}

	// 9. Case-folded / escaped field spellings still checked.
	for _, g := range []string{
		`{"DATASETS":[{"NAME":"a\uD800","UPSTREAMS":[]}]}`,
		`{"datasets":[{"name":"a\uD800","upstreams":[]}]}`,
	} {
		if _, err := chainledger.UnmarshalGraphFile([]byte(g)); err == nil {
			fmt.Println("FAIL: case/escaped field bypassed check:", g)
		} else {
			fmt.Println("OK folded/escaped field checked:", err)
		}
	}
}
